<?php require_once "../db.php"; require_role("Admin"); $id=(int)($_GET['id']??0); $st=$conn->prepare("SELECT id,name,email,course,semester FROM student WHERE id=?");$st->bind_param("i",$id);$st->execute();$student=$st->get_result()->fetch_assoc();if(!$student){http_response_code(404);die('Student not found. <a href="students.php">Back to students</a>');}
$a=$conn->prepare("SELECT h.*,q.title,q.subject FROM quiz_history h JOIN quiz q ON q.id=h.quiz_id WHERE h.student_id=? ORDER BY h.created_at DESC,h.id DESC");$a->bind_param("i",$id);$a->execute();$history=$a->get_result();$b=$conn->prepare("SELECT h.*,m.title,m.subject FROM practice_history h JOIN practice_material m ON m.id=h.material_id WHERE h.student_id=? ORDER BY h.created_at DESC,h.id DESC");$b->bind_param("i",$id);$b->execute();$practice=$b->get_result(); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student History</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container-fluid"><div class="row"><div class="col-lg-2 p-0"><?php include "../partials/admin_sidebar.php";?></div><main class="col-lg-10"><div class="py-4 px-lg-3"><a href="students.php" class="btn btn-sm btn-outline-secondary mb-3">← Students</a><h2 class="fw-bold"><?=e($student['name'])?> — History</h2><p class="text-muted"><?=e($student['email'])?> · <?=e($student['course'])?> · <?=e($student['semester'])?></p>
<div class="card panel-card mb-4"><div class="card-body"><h5>Quiz Attempts</h5><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Quiz</th><th>Subject</th><th>Score</th><th>Correct / Wrong</th><th>Date</th></tr></thead><tbody><?php if(!$history->num_rows):?><tr><td colspan="5" class="text-muted">No quiz attempts yet.</td></tr><?php endif;?><?php while($h=$history->fetch_assoc()):?><tr><td><a href="quiz_attempt.php?id=<?=$h['id']?>"><?=e($h['title'])?></a></td><td><?=e($h['subject'])?></td><td><?=$h['score']?>/<?=$h['total_questions']?></td><td><?=$h['correct_answers']?> / <?=$h['wrong_answers']?></td><td><a href="quiz_attempt.php?id=<?=$h['id']?>"><?=e($h['created_at'])?></a></td></tr><?php endwhile;?></tbody></table></div></div></div>
<div class="card panel-card"><div class="card-body"><h5>Practice History</h5><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Material</th><th>Subject</th><th>Score</th><th>Correct / Wrong</th><th>Date</th></tr></thead><tbody><?php if(!$practice->num_rows):?><tr><td colspan="5" class="text-muted">No practice attempts yet.</td></tr><?php endif;?><?php while($h=$practice->fetch_assoc()):?><tr><td><?=e($h['title'])?></td><td><?=e($h['subject'])?></td><td><?=$h['score']?>/<?=$h['total_questions']?></td><td><?=$h['correct_answers']?> / <?=$h['wrong_answers']?></td><td><?=e($h['created_at'])?></td></tr><?php endwhile;?></tbody></table></div></div></div></div></main></div></div><script src="../assets/card-links.js"></script></body></html>
